    pub(super) fn inverse(&self,values:&[K],abc:[K;3])->Result<Vec<K>,Error>{
        if self.0.len()>Q || values.len()!=4*self.0.len(){return Err(Error::Shape);}
        if values.is_empty() || values.iter().any(|v|*v==K::ZERO){return Err(Error::Domain);}
