                denoms.push(p.abc[0].add(p.abc[1].mul_m31(x)).add(p.abc[2].mul_m31(y)));
                numerators.push(combined[i][j].sub(p.iv[0].add(p.iv[1].mul_m31(if p.use_x{x}else{y}))));
            }
