}
fn inject(weights:&mut WeightAccumulator,c:&mut K,values:&[K],xs:&[M31],rho:K)->Result<K,Error>{
    let mut power=rho;let scales:Vec<K>=(0..values.len()).map(|_|{let a=power;power=power.mul(rho);a}).collect();
